// Sample shader: scales image brightness by intensity.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> intensity: f32; // Brightness multiplier. 0 to 2, default 1
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  var color = textureSample(inputImage, inputImageSampler, v_uv);
  color = vec4f(color.rgb * intensity, color.a);
  return color;
}

// Blends two images using a mix factor.
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;
@group(0) @binding(4) var<uniform> mixFactor: f32; // Blend ratio. 0 = first image, 1 = second. Default 0.5
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return mix(a, b, mixFactor);
}

// Passes the input image through unchanged (identity/resample).
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  return textureSample(inputImage, inputImageSampler, v_uv);
}

// Detects edges using the Sobel operator.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> intensity: f32; // Edge strength multiplier. 0–5, default 1

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputImage));

  let tl = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x, -px.y)).rgb, vec3f(0.299, 0.587, 0.114));
  let t  = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f(  0.0, -px.y)).rgb, vec3f(0.299, 0.587, 0.114));
  let tr = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x, -px.y)).rgb, vec3f(0.299, 0.587, 0.114));
  let l  = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x,   0.0)).rgb, vec3f(0.299, 0.587, 0.114));
  let r  = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,   0.0)).rgb, vec3f(0.299, 0.587, 0.114));
  let bl = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x,  px.y)).rgb, vec3f(0.299, 0.587, 0.114));
  let b  = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f(  0.0,  px.y)).rgb, vec3f(0.299, 0.587, 0.114));
  let br = dot(textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,  px.y)).rgb, vec3f(0.299, 0.587, 0.114));

  let gx = -tl - 2.0 * l - bl + tr + 2.0 * r + br;
  let gy = -tl - 2.0 * t - tr + bl + 2.0 * b + br;
  let edge = sqrt(gx * gx + gy * gy) * intensity;

  return vec4f(vec3f(edge), 1.0);
}

// Applies a 3×3 Gaussian blur kernel.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputImage));

  var col = vec4f(0.0);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x, -px.y)) * 0.0625;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 0.0,  -px.y)) * 0.125;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x, -px.y)) * 0.0625;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x,  0.0))  * 0.125;
  col += textureSample(inputImage, inputImageSampler, v_uv)                        * 0.25;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,  0.0))  * 0.125;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x,  px.y)) * 0.0625;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 0.0,   px.y)) * 0.125;
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,  px.y)) * 0.0625;

  return col;
}

// Applies a 3×3 box (mean) blur.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputImage));

  var col = vec4f(0.0);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f(-1.0, -1.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 0.0, -1.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 1.0, -1.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f(-1.0,  0.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 1.0,  0.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f(-1.0,  1.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 0.0,  1.0) * px);
  col += textureSample(inputImage, inputImageSampler, v_uv + vec2f( 1.0,  1.0) * px);
  return col / 9.0;
}

// Sharpens the image using unsharp masking.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> strength: f32; // Sharpening intensity. 0–10, default 1

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputImage));

  let center = textureSample(inputImage, inputImageSampler, v_uv);
  var blur =
    textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x, -px.y)) +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f( 0.0,  -px.y)) +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x, -px.y)) +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x,  0.0))  +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,  0.0))  +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x,  px.y)) +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f( 0.0,   px.y)) +
    textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,  px.y));
  blur /= 8.0;

  return center + (center - blur) * strength;
}

// Applies an emboss (relief) effect.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let px = 1.0 / vec2f(textureDimensions(inputImage));

  let col =
    textureSample(inputImage, inputImageSampler, v_uv + vec2f(-px.x, -px.y)) -
    textureSample(inputImage, inputImageSampler, v_uv + vec2f( px.x,  px.y));
  let gray = dot(col.rgb, vec3f(0.299, 0.587, 0.114)) + 0.5;

  return vec4f(vec3f(gray), 1.0);
}

// Reduces resolution into blocky pixels.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> blockSize: vec2f; // Block size in pixels (width, height). Default (8, 8)

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let size = vec2f(textureDimensions(inputImage));
  let blocks = size / max(blockSize, vec2f(1.0));
  let uv = floor(v_uv * blocks) / blocks;
  return textureSample(inputImage, inputImageSampler, uv);
}

// Inverts RGB channels (negative image).
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let col = textureSample(inputImage, inputImageSampler, v_uv);
  return vec4f(1.0 - col.rgb, col.a);
}

// Converts to grayscale using luminance weights.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let col = textureSample(inputImage, inputImageSampler, v_uv);
  let gray = dot(col.rgb, vec3f(0.299, 0.587, 0.114));
  return vec4f(vec3f(gray), col.a);
}

// Adjusts brightness and contrast.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> brightness: f32; // Additive brightness. -1 to 1, default 0
@group(0) @binding(3) var<uniform> contrast: f32; // Contrast multiplier. 0 to 4, default 1

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let c = textureSample(inputImage, inputImageSampler, v_uv);
  let adjusted = (c.rgb - vec3f(0.5)) * max(contrast, 0.0) + vec3f(0.5) + vec3f(brightness);
  return vec4f(clamp(adjusted, vec3f(0.0), vec3f(1.0)), c.a);
}

// Rotates hue in HSV color space.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> angle: f32; // Rotation angle in radians. 0 to 2π

fn rgb2hsv(c: vec3f) -> vec3f {
  let K = vec4f(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  let p = mix(vec4f(c.bg, K.wz), vec4f(c.gb, K.xy), step(c.b, c.g));
  let q = mix(vec4f(p.xyw, c.r), vec4f(c.r, p.yzx), step(p.x, c.r));
  let d = q.x - min(q.w, q.y);
  let e = 1.0e-10;
  return vec3f(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

fn hsv2rgb(c: vec3f) -> vec3f {
  let K = vec4f(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  let p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, vec3f(0.0), vec3f(1.0)), c.y);
}

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let col = textureSample(inputImage, inputImageSampler, v_uv);
  let hsv = rgb2hsv(col.rgb);
  let h = fract(hsv.x + angle / 6.28318530718);
  return vec4f(hsv2rgb(vec3f(h, hsv.y, hsv.z)), col.a);
}

// Converts to black/white at a luminance threshold.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> threshold: f32; // Luminance cutoff. 0 to 1, default 0.5

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let col = textureSample(inputImage, inputImageSampler, v_uv);
  let lum = dot(col.rgb, vec3f(0.299, 0.587, 0.114));
  let bw = step(threshold, lum);
  return vec4f(vec3f(bw), col.a);
}

// Applies a warm sepia tone.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let col = textureSample(inputImage, inputImageSampler, v_uv);
  let r = dot(col.rgb, vec3f(0.393, 0.769, 0.189));
  let g = dot(col.rgb, vec3f(0.349, 0.686, 0.168));
  let b = dot(col.rgb, vec3f(0.272, 0.534, 0.131));
  return vec4f(min(r, 1.0), min(g, 1.0), min(b, 1.0), col.a);
}

// Maps luminance to a turbo colormap (scientific visualization).
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;

fn turbo(t: f32) -> vec3f {
  let a = vec3f(0.114, 0.056, 0.566);
  let b = vec3f(0.376, 0.763, 0.843);
  let c = vec3f(0.267, 0.472, 0.090);
  let d = vec3f(0.905, 0.811, 0.011);
  let e = vec3f(0.740, 0.080, 0.055);

  var r: vec3f;
  if (t < 0.25) { r = mix(a, b, t / 0.25); }
  else if (t < 0.5) { r = mix(b, c, (t - 0.25) / 0.25); }
  else if (t < 0.75) { r = mix(c, d, (t - 0.5) / 0.25); }
  else { r = mix(d, e, (t - 0.75) / 0.25); }
  return r;
}

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let raw = textureSample(inputImage, inputImageSampler, v_uv);
  let v = raw.g;
  let color = turbo(clamp(v, 0.0, 1.0));
  return vec4f(color, 1.0);
}

// Outputs a solid color.
@group(0) @binding(0) var<uniform> color: vec4f; // RGBA color value
@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  return color;
}

// Horizontal linear gradient between two colors.
@group(0) @binding(0) var<uniform> colorA: vec4f; // Left edge color
@group(0) @binding(1) var<uniform> colorB: vec4f; // Right edge color
@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  return mix(colorA, colorB, v_uv.x);
}

// Generates a checkerboard pattern.
@group(0) @binding(0) var<uniform> gridSize: vec2f; // Number of cells (columns, rows). Default (8, 8)
@group(0) @binding(1) var<uniform> color1: vec4f; // First square color
@group(0) @binding(2) var<uniform> color2: vec4f; // Second square color
@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let cell = floor(v_uv * max(gridSize, vec2f(1.0)));
  let checker = (cell.x + cell.y) % 2.0;
  return mix(color1, color2, checker);
}

// Generates value noise.
@group(0) @binding(0) var<uniform> scale: f32; // Noise frequency. Higher = finer detail. Default 10
fn hash(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn valueNoise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (vec2f(3.0) - 2.0 * f);
  let a = hash(i);
  let b = hash(i + vec2f(1.0, 0.0));
  let c = hash(i + vec2f(0.0, 1.0));
  let d = hash(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let n = valueNoise(v_uv * max(scale, 1.0));
  return vec4f(vec3f(n), 1.0);
}

// Draws a filled circle.
@group(0) @binding(0) var<uniform> circle: vec4f; // Circle parameters (centerX, centerY, radius, unused). Default (0.5, 0.5, 0.25, 0)
@fragment fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let center = circle.xy;
  let radius = circle.z;
  let dist = length(v_uv - center);
  let mask = 1.0 - step(radius, dist);
  return vec4f(vec3f(mask), 1.0);
}

// Adds two images (clamped to white).
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return min(a + b, vec4f(1.0));
}

// Multiplies two images (darkens).
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return a * b;
}

// Screen blend (brightens, opposite of multiply).
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return vec4f(1.0) - (vec4f(1.0) - a) * (vec4f(1.0) - b);
}

// Overlay blend (combines multiply and screen).
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

fn overlay(base: vec3f, blend: vec3f) -> vec3f {
  return mix(
    2.0 * base * blend,
    vec3f(1.0) - 2.0 * (vec3f(1.0) - base) * (vec3f(1.0) - blend),
    step(vec3f(0.5), base)
  );
}

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return vec4f(overlay(a.rgb, b.rgb), max(a.a, b.a));
}

// Absolute difference between two images.
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return vec4f(abs(a.rgb - b.rgb), max(a.a, b.a));
}

// Exclusion blend (similar to difference, lower contrast).
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return vec4f(a.rgb + b.rgb - 2.0 * a.rgb * b.rgb, max(a.a, b.a));
}

// Soft light blend (gentle dodging/burning).
@group(0) @binding(0) var inputA: texture_2d<f32>;
@group(0) @binding(1) var inputASampler: sampler;
@group(0) @binding(2) var inputB: texture_2d<f32>;
@group(0) @binding(3) var inputBSampler: sampler;

fn softLight(base: vec3f, blend: vec3f) -> vec3f {
  let lo = 2.0 * base * blend + base * base * (vec3f(1.0) - 2.0 * blend);
  let hi = 2.0 * base * (vec3f(1.0) - blend) + sqrt(base) * (2.0 * blend - vec3f(1.0));
  return mix(lo, hi, step(vec3f(0.5), blend));
}

@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let a = textureSample(inputA, inputASampler, v_uv);
  let b = textureSample(inputB, inputBSampler, v_uv);
  return vec4f(softLight(a.rgb, b.rgb), max(a.a, b.a));
}

// Twirls the image around the center.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> radius: f32; // Twirl radius. 0 to 1, default 0.5
@group(0) @binding(3) var<uniform> angle: f32; // Twirl angle in radians. -10 to 10, default 3
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let center = vec2f(0.5);
  var uv = v_uv - center;
  let dist = length(uv);
  let factor = max(1.0 - dist / max(radius, 0.001), 0.0);
  let a = angle * factor * factor;
  let s = sin(a);
  let c = cos(a);
  uv = vec2f(uv.x * c - uv.y * s, uv.x * s + uv.y * c);
  return textureSample(inputImage, inputImageSampler, uv + center);
}

// Applies a sinusoidal wave distortion.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> frequency: f32; // Wave frequency. 1 to 50, default 10
@group(0) @binding(3) var<uniform> amplitude: f32; // Wave amplitude. 0 to 0.1, default 0.02
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  var uv = v_uv;
  uv.x += sin(uv.y * frequency) * amplitude;
  uv.y += sin(uv.x * frequency) * amplitude;
  return textureSample(inputImage, inputImageSampler, uv);
}

// Displaces pixels using a displacement map.
@group(0) @binding(0) var displaceMap: texture_2d<f32>;
@group(0) @binding(1) var displaceMapSampler: sampler;
@group(0) @binding(2) var inputImage: texture_2d<f32>;
@group(0) @binding(3) var inputImageSampler: sampler;
@group(0) @binding(4) var<uniform> strength: f32; // Displacement strength. 0 to 1, default 0.1
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let disp = textureSample(displaceMap, displaceMapSampler, v_uv);
  let offset = (disp.rg - vec2f(0.5)) * 2.0 * strength;
  return textureSample(inputImage, inputImageSampler, v_uv + offset);
}

// Applies barrel/pincushion lens distortion.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> k1: f32; // Quadratic distortion coefficient. -1 to 1
@group(0) @binding(3) var<uniform> k2: f32; // Quartic distortion coefficient. -1 to 1
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let uv = v_uv * 2.0 - vec2f(1.0);
  let r2 = dot(uv, uv);
  let distortion = 1.0 + k1 * r2 + k2 * r2 * r2;
  let distorted = uv * distortion * 0.5 + vec2f(0.5);
  if (distorted.x < 0.0 || distorted.x > 1.0 || distorted.y < 0.0 || distorted.y > 1.0) {
    return vec4f(0.0);
  }
  return textureSample(inputImage, inputImageSampler, distorted);
}

// Pinches or expands the image radially.
@group(0) @binding(0) var inputImage: texture_2d<f32>;
@group(0) @binding(1) var inputImageSampler: sampler;
@group(0) @binding(2) var<uniform> radius: f32; // Effect radius. 0 to 1, default 0.5
@group(0) @binding(3) var<uniform> strength: f32; // Pinch strength. -2 to 2, default 0.5
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
  let center = vec2f(0.5);
  var uv = v_uv - center;
  let dist = length(uv);
  let r = max(radius, 0.001);
  if (dist < r) {
    let factor = dist / r;
    let pinch = pow(factor, 1.0 + strength) * r;
    uv = normalize(uv) * pinch;
  }
  return textureSample(inputImage, inputImageSampler, uv + center);
}

// Simulates Gray-Scott reaction-diffusion patterns.
@group(0) @binding(0) var<uniform> dA: f32; // Diffusion rate of chemical A. Default 0.21
@group(0) @binding(1) var<uniform> dB: f32; // Diffusion rate of chemical B. Default 0.105
@group(0) @binding(2) var<uniform> feedRate: f32; // Feed rate (F). Default 0.055
@group(0) @binding(3) var<uniform> killRate: f32; // Kill rate (k). Default 0.062
@group(0) @binding(4) var<uniform> timestep: f32; // Simulation time step. Default 1.0
@fragment
fn main(@location(0) v_uv: vec2f) -> @location(0) vec4f {
    let uv = v_uv;

    if (iFrame < 0.5) {
        var a = 1.0;
        var b = 0.0;
        let center = vec2f(0.5);
        let halfSeed = vec2f(0.06);
        let d = abs(uv - center);
        if (d.x < halfSeed.x && d.y < halfSeed.y) {
            a = 0.5;
            b = 0.25;
        }
        return vec4f(a, b, 0.0, 1.0);
    }

    let px = vec2f(1.0) / vec2f(textureDimensions(previousFrame));
    let c = textureSample(previousFrame, previousFrameSampler, uv);
    var a = c.r;
    var b = c.g;

    let up    = textureSample(previousFrame, previousFrameSampler, uv + vec2f(0.0, px.y)).rg;
    let down  = textureSample(previousFrame, previousFrameSampler, uv - vec2f(0.0, px.y)).rg;
    let left  = textureSample(previousFrame, previousFrameSampler, uv - vec2f(px.x, 0.0)).rg;
    let right = textureSample(previousFrame, previousFrameSampler, uv + vec2f(px.x, 0.0)).rg;

    let la = up.r + down.r + left.r + right.r - 4.0 * a;
    let lb = up.g + down.g + left.g + right.g - 4.0 * b;

    let rxn = a * b * b;
    a += (dA * la - rxn + feedRate * (1.0 - a)) * timestep;
    b += (dB * lb + rxn - (feedRate + killRate) * b) * timestep;

    return vec4f(clamp(a, 0.0, 1.0), clamp(b, 0.0, 1.0), 0.0, 1.0);
}
